UPDATE tdm52_chck_manl
   SET tdm52_checker_id   = #{personId}
     , tdm52_upd_nm       = #{updName}
     , tdm52_upd_date     = f_sysdate()
 WHERE tdm52_chck_manl_id = #{chckManlId}
   AND tdm52_company_id   = #{companyId}

mapper.select:
SELECT FROM ( SELECT tdm52_chck_manl.* , tdm43_manl_org_id , tdm43_role_id AS tdm52_role_id , tdm43_role_nm AS tdm52_role_nm , tdm43_org_id AS tdm52_org_id , f_emp_kor_nm(tdm52_checker_id) AS tdm52_checker_nm , f_cdnm('TdmCheckResult', tdm52_check_result_cd, tdm52_company_id, f_today()) AS tdm52_check_result_nm , f_cdnm('TdmCheckStatus', tdm52_check_status_cd, tdm52_company_id, f_today()) AS tdm52_check_status_nm , tdm51_check_ym AS tdm52_check_ym , tdm51_chck_job_id AS tdm52_chck_job_id , CONCAT('('||tdm43_manl_cd||') ', tdm43_check_item) AS tdm52_check_item , f_get_tdmCheckCycle(tdm43_manl_id) AS tdm52_check_cycle_info , tdm43_check_evid_doc_nm AS tdm52_check_evid_doc_nm , tdm43_check_how AS tdm52_check_how , tdm43_ref_basis AS tdm52_ref_basis , CASE WHEN tdm10_common_yn = 'true' THEN '공통' ELSE '지정' END AS tdm52_common_type_nm , tdm43_task_nm AS tdm52_task_nm , tdm43_task_relate_detail_nm AS task_detail_nm , tdm43_task_relate_duty_nm AS task_duty_nm , tdm43_manl_cd AS manl_cd , f_get_tdmEvidCount(tdm52_chck_manl_id) ||'건' AS tdm52_file_count_str FROM tdm52_chck_manl INNER JOIN tdm51_chck_org ON tdm51_chck_org_id = tdm52_chck_org_id INNER JOIN tdm43_manl ON tdm43_manl_id = tdm52_manl_id INNER JOIN tdm10_task ON tdm10_task_id = tdm43_task_id WHERE tdm52_chck_org_id = #{chckOrgId} AND tdm52_checker_id = #{personId}
AND tdm52_check_status_cd IN ('10','11','26') /*(10:점검대기/11:점검진행/26:승인반려)*/
AND CONCAT(tdm43_manl_cd, tdm43_check_item) ILIKE '%'||#{searchText}||'%'
) t ORDER BY t.tdm52_role_nm COLLATE "ko_KR.utf8" , t.tdm52_task_nm COLLATE "ko_KR.utf8" , t.task_detail_nm COLLATE "ko_KR.utf8" , t.task_duty_nm COLLATE "ko_KR.utf8" , t.manl_cd

SELECT tdm52_chck_manl_id
  FROM tdm52_chck_manl
 WHERE tdm52_chck_org_id = #{chckOrgId}
   AND tdm52_checker_id  = #{personId}

   AND tdm52_check_status_cd IN ('10')      /*(10:점검대기)*/


   AND tdm52_check_status_cd IN ('11','19') /*(11:점검진행 / 19:점검완료)*/

mapper.update:
UPDATE tdm52_chck_manl
   SET tdm52_check_date        = CAST(#{checkDate} AS date)
     , tdm52_check_result_cd   = CAST(#{checkResultCode} AS varchar)
     , tdm52_check_cmnt        = CAST(#{checkCmnt} AS text)
     , tdm52_upd_nm            = #{updName}
     , tdm52_upd_date          = f_sysdate()
 WHERE tdm52_chck_manl_id      = #{chckManlId}
   AND tdm52_company_id        = #{companyId}

